const BRANDS = {
  "gemini": "data:image/svg+xml;base64,",
  "gemma": "data:image/svg+xml;base64,",
  "openai": "data:image/svg+xml;base64,",
  "mistral": "data:image/svg+xml;base64,",
  "qwen": "data:image/svg+xml;base64,",
  "deepseek": "data:image/svg+xml;base64,",
  "meta": "data:image/svg+xml;base64,",
  "zai": "data:image/svg+xml;base64,",
  "nvidia": "data:image/svg+xml;base64,",
  "openrouter": "data:image/svg+xml;base64,",
  "cloudflare": "data:image/svg+xml;base64,",
  "tencent": "data:image/svg+xml;base64,",
  "microsoft": "data:image/svg+xml;base64,",
  "moonshot": "data:image/svg+xml;base64,",
  "cohere": "data:image/svg+xml;base64,",
  "groq": "data:image/svg+xml;base64,",
  "poolside": "data:image/svg+xml;base64,",
  "sambanova": "data:image/svg+xml;base64,",
  "github": "data:image/svg+xml;base64,",
  "anthropic": "data:image/svg+xml;base64,",
  "minimax": "data:image/svg+xml;base64,",
  "xai": "data:image/svg+xml;base64,",
  "perplexity": "data:image/svg+xml;base64,",
  "reflection": "data:image/svg+xml;base64,",
  "kilo": "data:image/svg+xml;base64,",
  "bazaarlink": "data:image/svg+xml;base64,",
  "recursive": "data:image/png;base64,",
  "orcarouter": "data:image/png;base64,",
  "llm7": "data:image/png;base64,",
  "ovh": "data:image/svg+xml;base64,"
};

// Model maker takes precedence over the infrastructure provider. Unknown
// models use a neutral icon, never the router's logo or invented initials.
const BRAND_RULES = [
  [/gemma/i, "gemma"], [/gemini/i, "gemini"], [/gpt|openai|\bo[134]\b/i, "openai"],
  [/mistral|ministral|codestral|magistral|pixtral|devstral/i, "mistral"], [/qwen|qwq/i, "qwen"],
  [/deepseek/i, "deepseek"], [/llama|meta-|\bmeta\b/i, "meta"], [/glm|z-ai|zai|zhipu/i, "zai"],
  [/nemotron|nvidia/i, "nvidia"], [/hunyuan|tencent|\bhy\d/i, "tencent"],
  [/\bphi-?\d|microsoft/i, "microsoft"], [/kimi|moonshot/i, "moonshot"],
  [/reflection|\bbeam\b/i, "reflection"], [/recursive|\bflint\b/i, "recursive"],
  [/poolside|laguna/i, "poolside"], [/cohere|north-mini/i, "cohere"], [/kilo-auto/i, "kilo"],
  [/claude|anthropic/i, "anthropic"], [/minimax/i, "minimax"], [/grok|x-ai|\bxai\b/i, "xai"],
  [/perplexity|sonar/i, "perplexity"], [/openrouter/i, "openrouter"],
];
const PROVIDER_BRANDS = { gemini: "gemini", mistral: "mistral", zai: "zai", cloudflare: "cloudflare", openrouter: "openrouter",
  ghmodels: "github", groq: "groq", ovh: "ovh", sambanova: "sambanova", llm7: "llm7", kilo: "kilo",
  bazaarlink: "bazaarlink", orcarouter: "orcarouter" };

function brandOf(model, provider) {
  for (const text of [(model && model.title) || "", (model && model.id) || ""]) {
    for (const [pattern, name] of BRAND_RULES) if (pattern.test(text)) return name;
  }
  return (!model && PROVIDER_BRANDS[provider && provider.key]) || "";
}

function brandMark(name, extra = "") {
  const holder = document.createElement("span");
  holder.className = `brand ${extra}`;
  holder.setAttribute("aria-hidden", "true");
  if (Object.prototype.hasOwnProperty.call(BRANDS, name)) {
    holder.classList.add("brand-official");
    const image = document.createElement("img");
    image.src = BRANDS[name];
    image.alt = "";
    image.decoding = "async";
    holder.appendChild(image);
  } else {
    holder.classList.add("brand-generic");
    holder.innerHTML = `<svg class="ic" viewBox="0 0 24 24" aria-hidden="true">${ICONS.ai}</svg>`;
  }
  return holder;
}
